'use client';
import { useState, useEffect, useRef, useCallback, type ReactNode, type FormEvent } from 'react';
import { ShoppingBasket, ClipboardList, CalendarDays, Store, ChefHat, Users, PieChart, Settings, Search, Plus, ArrowUpRight, ArrowLeft, Star, Check, Trash2, Copy, MapPin, Leaf, ChevronLeft, ChevronRight, X, Download, RefreshCw, WifiOff, CheckCircle2, Mic, ScanLine, Flag, Minus, ExternalLink, Pencil, Archive, Menu, Sun, Moon, Link as LinkIcon, Clock, Heart, ShieldCheck } from 'lucide-react';
import { type State, type ShoppingList, type Item, type Recipe, type Product, type Source, categories, categoryEmoji, stores, money, listTotal, normalizedName } from '../lib/model';

import WeeklyPlanner from './weekly-planner';

type Page='planner'|'home'|'calendar'|'catalog'|'recipes'|'groups'|'spending'|'settings';
type ModalData={kind:string;list?:ShoppingList;item?:Item;recipe?:Recipe;product?:Product;groupId?:string;token?:string};
const navigation=[{id:'planner',name:'Меню на неделю',icon:ChefHat},{id:'home',name:'Мои списки',icon:ClipboardList},{id:'calendar',name:'Календарь',icon:CalendarDays},{id:'catalog',name:'Магазины',icon:Store},{id:'recipes',name:'Рецепты',icon:ChefHat},{id:'groups',name:'Покупаем вместе',icon:Users},{id:'spending',name:'Расходы',icon:PieChart}];
const localDate=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const humanDate=(date:string)=>new Date(date+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
const field=(form:FormData,key:string)=>String(form.get(key)||'').trim();
const num=(form:FormData,key:string,fallback=0)=>{const raw=field(form,key);return raw?Number(raw.replace(',','.')):fallback;};
const price=(form:FormData,key:string)=>field(form,key)===''?null:Math.round(num(form,key)*100);
const getItems=(state:State,listId:string)=>state.items.filter(i=>i.listId===listId&&!i.deleted);

function Modal({title,subtitle,children,onClose}:{title:string;subtitle?:string;children:ReactNode;onClose:()=>void}){
  const ref=useRef<HTMLDivElement>(null);
  useEffect(()=>{const old=document.activeElement as HTMLElement;const focusable=()=>Array.from(ref.current?.querySelectorAll<HTMLElement>('button,input,select,textarea,a[href]')||[]).filter(el=>!el.hasAttribute('disabled'));const firstInput=ref.current?.querySelector<HTMLElement>('input:not([type=checkbox])');(firstInput||focusable()[0])?.focus();const key=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose();if(event.key==='Tab'){const els=focusable(),first=els[0],last=els.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}};document.addEventListener('keydown',key);document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',key);document.body.style.overflow='';old?.focus();};},[onClose]);
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div ref={ref} className="modal" role="dialog" aria-modal="true" aria-label={title}><header className="modal-head"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="icon-btn" aria-label="Закрыть окно" onClick={onClose}><X size={20}/></button></header>{children}</div></div>;
}
function Empty({emoji,title,text,children}:{emoji:string;title:string;text:string;children?:ReactNode}){return <div className="empty"><div className="empty-emoji">{emoji}</div><h3>{title}</h3><p>{text}</p>{children}</div>;}
function RecipeCard({recipe,favorite,onOpen,onFavorite}:{recipe:Recipe;favorite:boolean;onOpen:()=>void;onFavorite:()=>void}){return <article className="recipe-card"><div className="recipe-art" style={{background:recipe.color}}><button className="recipe-open-art" onClick={onOpen} aria-label={'Открыть рецепт '+recipe.name}><span className="food-dish">{recipe.emoji}</span><span className="art-dot dot-a"/><span className="art-dot dot-b"/></button><button className={'recipe-heart '+(favorite?'saved':'')} onClick={onFavorite} aria-label={favorite?'Убрать рецепт из избранного':'Сохранить рецепт'}><Heart size={17} fill={favorite?'currentColor':'none'}/></button><span className="recipe-tag">{recipe.category}</span></div><button className="recipe-card-body" onClick={onOpen}><h3>{recipe.name}</h3><p>{recipe.subtitle}</p><div><span><Clock size={14}/>{recipe.time} мин</span><span><Users size={14}/>{recipe.portions} порции</span>{recipe.own&&<span>Мой рецепт</span>}</div></button></article>;}

export default function ShoppingApp({initial}:{initial:State}){
  const [state,setState]=useState(initial),[page,setPage]=useState<Page>('planner'),[selected,setSelected]=useState<string|null>(null),[modal,setModal]=useState<ModalData|null>(null),[toast,setToast]=useState(''),[busy,setBusy]=useState(false),[offline,setOffline]=useState(false),[mobileMenu,setMobileMenu]=useState(false),[search,setSearch]=useState(''),[listFilter,setListFilter]=useState('Все'),[onlyItemFavorites,setOnlyItemFavorites]=useState(false),[recipeFilter,setRecipeFilter]=useState('Все'),[storeFilter,setStoreFilter]=useState('all'),[compare,setCompare]=useState(false),[portions,setPortions]=useState(2),[recipeStep,setRecipeStep]=useState(0),[targetList,setTargetList]=useState(''),[calendarMonth,setCalendarMonth]=useState(new Date()),[calendarDay,setCalendarDay]=useState(localDate(new Date())),[inviteLink,setInviteLink]=useState(''),[installPrompt,setInstallPrompt]=useState<any>(null);
  const [catalogLimit,setCatalogLimit]=useState(48);useEffect(()=>setCatalogLimit(48),[storeFilter,search,compare]);
  const [scanError,setScanError]=useState('');const video=useRef<HTMLVideoElement>(null),stream=useRef<MediaStream|null>(null),scanTimer=useRef<ReturnType<typeof setTimeout>|null>(null),refreshSerial=useRef(0),running=useRef(false),syncingSources=useRef(false);
  const activeLists=state.lists.filter(l=>!l.archived),current=state.lists.find(l=>l.id===selected),favorites=JSON.parse(state.profile.recipeFavorites||'[]') as string[];
  const allActiveItems=state.items.filter(i=>activeLists.some(l=>l.id===i.listId)),remaining=allActiveItems.filter(i=>!i.bought),total=listTotal(allActiveItems),today=localDate(new Date());
  const notify=(message:string)=>{setToast(message);};
  async function refresh(){const serial=++refreshSerial.current;const response=await fetch('/api/app',{cache:'no-store'});if(!response.ok)throw new Error('Не удалось обновить данные');const data=await response.json() as State;if(serial===refreshSerial.current)setState(data);setOffline(false);}
  async function run(action:Record<string,unknown>,message=''){if(running.current)return null;running.current=true;setBusy(true);try{const response=await fetch('/api/app',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(action)}),result=await response.json() as {error?:string; id?:string; token?:string; message?:string};if(!response.ok){if(response.status===409)await refresh();throw new Error(result.error||'Не удалось сохранить');}await refresh();if(message)notify(message);return result;}catch(error){notify(error instanceof Error?error.message:'Не удалось сохранить изменения');setOffline(!navigator.onLine);return null;}finally{setBusy(false);running.current=false;}}
  function go(next:Page){setPage(next);setSelected(null);setSearch('');setMobileMenu(false);}
  const close=useCallback(()=>{setModal(null);setInviteLink('');setScanError('');},[]);
  useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(timer);},[toast]);
  useEffect(()=>{const theme=state.profile.theme;document.documentElement.dataset.theme=theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;},[state.profile.theme]);
  useEffect(()=>{const online=()=>{setOffline(false);refresh().catch(()=>setOffline(true));},off=()=>setOffline(true);window.addEventListener('online',online);window.addEventListener('offline',off);const timer=setInterval(()=>{if(!document.hidden&&!running.current)refresh().catch(()=>setOffline(true));},20000);const join=location.hash.startsWith('#join=')?location.hash.slice(6):null;if(join)setModal({kind:'join',token:join});const install=(event:Event)=>{event.preventDefault();setInstallPrompt(event);};window.addEventListener('beforeinstallprompt',install);if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});return()=>{clearInterval(timer);window.removeEventListener('online',online);window.removeEventListener('offline',off);window.removeEventListener('beforeinstallprompt',install);};},[]);
  async function syncCatalog(automatic=false){if(syncingSources.current)return;syncingSources.current=true;let success=0;try{for(const source of state.sources.filter(s=>s.enabled)){if(automatic&&source.status!=='error'&&source.lastAttempt&&Date.now()-Date.parse(source.lastAttempt)<6*3600000)continue;const response=await fetch('/api/app',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'sync',sourceId:source.id,automatic})});if(response.ok)success++;}await refresh();if(!automatic)notify(success?'Источники проверены. Статус обновления — ниже.':'Источники пока не подключены');}catch{notify('Не удалось проверить каталоги');}finally{syncingSources.current=false;}}
  useEffect(()=>{if(page==='catalog')void syncCatalog(true);},[page]);
  async function copyText(text:string){try{await navigator.clipboard.writeText(text);notify('Скопировано');}catch{notify('Копирование недоступно в этом браузере');}}
  async function exportFile(){try{const response=await fetch('/api/planner',{cache:'no-store'});if(!response.ok)throw new Error();const planner=await response.json();const blob=new Blob([JSON.stringify({...state,planner},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sobrano-'+today+'.json';a.click();URL.revokeObjectURL(url);}catch{notify('Не удалось скачать данные. Проверьте подключение.');}}
  function recipeFavorite(recipe:Recipe){void run({action:'profile',recipeFavorites:favorites.includes(recipe.id)?favorites.filter(id=>id!==recipe.id):[...favorites,recipe.id]});}
  function openRecipe(recipe:Recipe){setPortions(recipe.portions);setRecipeStep(0);setTargetList(activeLists[0]?.id||'');setModal({kind:'recipe',recipe});}
  function itemPatch(item:Item,patch:Record<string,unknown>){void run({action:'updateItem',id:item.id,revision:item.revision,...patch});}
  function listPatch(list:ShoppingList,patch:Record<string,unknown>){void run({action:'updateList',id:list.id,revision:list.revision,...patch});}
  async function dictate(){const Speech=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;if(!Speech){notify('Голосовой ввод недоступен. Можно добавить товар вручную.');return;}const recognition=new Speech();recognition.lang='ru-RU';recognition.onresult=(event:any)=>{const input=document.querySelector<HTMLInputElement>('#item-name');if(input){const setter=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value')?.set;setter?.call(input,event.results[0][0].transcript);input.dispatchEvent(new Event('input',{bubbles:true}));}};recognition.onerror=()=>notify('Не удалось распознать речь');recognition.start();}
  async function startScan(){setScanError('');try{const Detector=(window as any).BarcodeDetector;if(!Detector)throw new Error('Этот браузер не поддерживает сканирование. Введите штрихкод вручную.');stream.current=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});if(video.current){video.current.srcObject=stream.current;await video.current.play();}const detector=new Detector({formats:['ean_13','ean_8','upc_a','upc_e']});const tick=async()=>{if(!video.current||!stream.current)return;try{const results=await detector.detect(video.current);if(results.length){const code=results[0].rawValue;const input=document.querySelector<HTMLInputElement>('#item-barcode');if(input)input.value=code;const found=state.products.find(p=>p.barcode===code);if(found){const name=document.querySelector<HTMLInputElement>('#item-name');if(name)name.value=found.name;}notify('Штрихкод: '+code);stopScan();return;}}catch{}scanTimer.current=setTimeout(tick,450);};tick();}catch(error){setScanError(error instanceof Error?error.message:'Камера недоступна');stopScan();}}
  function stopScan(){stream.current?.getTracks().forEach(t=>t.stop());stream.current=null;if(scanTimer.current)clearTimeout(scanTimer.current);}
  useEffect(()=>{return()=>stopScan();},[modal?.kind]);
  async function submitList(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget),payload={name:field(form,'name'),icon:field(form,'icon')||'🛒',budget:Math.round(num(form,'budget')*100),date:field(form,'date')||null,groupId:field(form,'group')||null};if(modal?.list&&modal.list.role!=='owner')delete (payload as Partial<typeof payload>).groupId;const result=await run(modal?.list?{action:'updateList',id:modal.list.id,revision:modal.list.revision,...payload}:{action:'createList',...payload},modal?.list?'Список обновлён':'Новый список готов');if(result){close();if(result.id){setSelected(result.id||null);setPage('home');}}}
  async function submitItem(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget),payload={name:field(form,'name'),quantity:num(form,'quantity',1),unit:field(form,'unit'),price:price(form,'price'),category:field(form,'category'),note:field(form,'note'),important:form.has('important')?1:0};const result=await run(modal?.item?{action:'updateItem',id:modal.item.id,revision:modal.item.revision,...payload}:{action:'addItems',listId:modal?.list?.id||selected,items:[{...payload,barcode:field(form,'barcode')||null}]},modal?.item?'Покупка обновлена':'Добавлено в список');if(result)close();}
  const pageTitles:Record<Page,string>={planner:'Меню на неделю',home:'Мои списки',calendar:'Календарь покупок',catalog:'Каталоги магазинов',recipes:'Что приготовим?',groups:'Вместе проще',spending:'Покупки в цифрах',settings:'Ваше пространство'};

  function ListCard({list}:{list:ShoppingList}){const its=getItems(state,list.id),done=its.filter(i=>i.bought).length,amount=listTotal(its);return <article className={'list-card '+(list.archived?'archived':'')}><div className="card-top"><span className="list-emoji">{list.icon}</span><button className={'icon-btn '+(list.favorite?'gold':'')} disabled={busy||!['owner','editor'].includes(list.role||'')} aria-label={list.favorite?'Убрать список из избранного':'Сохранить список'} onClick={()=>listPatch(list,{favorite:list.favorite?0:1})}><Star size={18} fill={list.favorite?'currentColor':'none'}/></button></div><button className="list-open" onClick={()=>{setSelected(list.id);setSearch('');}}><h3>{list.name}</h3><p>{list.groupId?<><Users size={13}/> {state.groups.find(g=>g.id===list.groupId)?.name}</>:<>Личный список</>}{list.date&&<span> · {humanDate(list.date)}</span>}</p><div className="card-progress"><span style={{width:its.length?`${done/its.length*100}%`:'0%'}}/></div><div className="list-card-bottom"><span>{done} из {its.length} куплено</span><strong>{money(amount)}</strong></div></button></article>;}

  return <div className="app-shell"><aside className={'sidebar '+(mobileMenu?'mobile-open':'')}><button className="brand" onClick={()=>go('home')} aria-label="Собрано — главная"><span className="brand-mark"><ShoppingBasket size={26}/></span><span>собрано<span className="brand-dot">.</span></span></button><p className="sidebar-caption">Покупки с хорошим планом</p><div className="nav-label">ВАШЕ ПРОСТРАНСТВО</div><nav aria-label="Основные разделы">{navigation.map(n=><button key={n.id} className={'nav-item '+(page===n.id?'active':'')} onClick={()=>go(n.id as Page)}><n.icon size={19}/><span>{n.name}</span>{n.id==='home'&&activeLists.length>0&&<b>{activeLists.length}</b>}</button>)}</nav><div className="sidebar-note"><Leaf size={21}/><h4>Меньше суеты.<br/>Больше хорошего.</h4><p>Планируйте покупки,<br/>остальное — по списку.</p><span className="sidebar-note-line"/></div><div className="sidebar-bottom"><button className={'nav-item '+(page==='settings'?'active':'')} onClick={()=>go('settings')}><Settings size={18}/>Настройки</button><button className="profile" onClick={()=>go('settings')}><span className="avatar">{state.profile.name.slice(0,1).toUpperCase()}</span><span><strong>{state.profile.name}</strong><small>Личное пространство</small></span><ChevronRight size={16}/></button></div></aside>{mobileMenu&&<button className="menu-scrim" aria-label="Закрыть меню" onClick={()=>setMobileMenu(false)}/>}
    <div className="workspace"><header className="topbar"><div className="breadcrumbs"><button className="mobile-menu icon-btn" aria-label="Меню" onClick={()=>setMobileMenu(true)}><Menu size={22}/></button><span>Моё пространство</span><ChevronRight size={13}/><strong>{current?current.name:pageTitles[page]}</strong></div><div className="topbar-right"><button className="city" onClick={()=>go('settings')}><MapPin size={15}/>{state.profile.city}</button><span className={'sync-status '+(offline?'error':'')}>{offline?<WifiOff size={14}/>:<span className="status-dot"/>}{offline?'Нет связи':busy?'Сохраняем…':'Сохранено'}</span><button className="avatar small" onClick={()=>go('settings')} aria-label="Профиль">{state.profile.name.slice(0,1).toUpperCase()}</button></div></header>
    <main className="main-content">{offline&&<div className="notice warning"><WifiOff size={18}/><span>Связь с сервером прервалась. Изменения считаются сохранёнными только после подтверждения.</span><button onClick={()=>refresh().catch(()=>notify('Сервер пока недоступен'))}>Повторить</button></div>}
    {current ? <><button className="back-link" onClick={()=>setSelected(null)}><ArrowLeft size={16}/>К спискам</button><div className="page-heading"><div><div className="eyebrow">{current.groupId?'СОВМЕСТНЫЕ ПОКУПКИ':'ЛИЧНЫЙ СПИСОК'}{current.date?' · '+humanDate(current.date):''}</div><h1><span className="title-emoji">{current.icon}</span>{current.name}</h1></div><div className="heading-actions"><button className="secondary" onClick={()=>copyText(current.name+'\n'+getItems(state,current.id).map(i=>`${i.bought?'✓':'☐'} ${i.name} — ${i.quantity} ${i.unit}${i.price!==null?' · '+money(Math.round(i.price*i.quantity)):''}`).join('\n'))}><Copy size={16}/><span>Копировать</span></button>{['owner','editor'].includes(current.role||'')&&<button className="secondary icon-btn" aria-label="Настройки списка" onClick={()=>setModal({kind:'list',list:current})}><Pencil size={17}/></button>}<button className="primary" disabled={busy||current.archived===1||!['owner','editor'].includes(current.role||'')} onClick={()=>setModal({kind:'item',list:current})}><Plus size={18}/>Добавить товар</button></div></div>
      <div className="detail-layout"><section><div className="list-toolbar"><div className="searchbox"><Search size={17}/><input aria-label="Поиск в списке" placeholder="Найти покупку" value={search} onChange={e=>setSearch(e.target.value)}/></div><button className="secondary" onClick={()=>setOnlyItemFavorites(!onlyItemFavorites)}><Star size={16}/><span>Избранное</span></button></div><div className="items-panel">{getItems(state,current.id).length===0?<Empty emoji="🧺" title="Начнём с первой покупки" text="Добавляйте свои товары или перенесите ингредиенты из рецепта."><button className="primary" disabled={current.archived===1||!['owner','editor'].includes(current.role||'')} onClick={()=>setModal({kind:'item',list:current})}><Plus size={17}/>Добавить товар</button></Empty>:<>{[...new Set(getItems(state,current.id).map(i=>i.category))].map(category=>{const rows=getItems(state,current.id).filter(i=>i.category===category&&normalizedName(i.name).includes(normalizedName(search))&&(!onlyItemFavorites||i.favorite)).sort((a,b)=>a.bought-b.bought||b.important-a.important);if(!rows.length)return null;return <section key={category} className="item-category"><h3><span>{categoryEmoji[category]||'📦'}</span>{category}<b>{rows.length}</b></h3>{rows.map(item=><div className={'item-row '+(item.bought?'bought':'')} key={item.id}><button className={'check-box '+(item.bought?'checked':'')} disabled={busy||current.archived===1||current.role==='viewer'} aria-label={item.bought?'Вернуть в покупки '+item.name:'Отметить купленным '+item.name} onClick={()=>itemPatch(item,{bought:item.bought?0:1})}>{item.bought&&<Check size={15}/>}</button><button className="item-info" disabled={!['owner','editor'].includes(current.role||'')} onClick={()=>setModal({kind:'item',item,list:current})}><strong>{item.name}{item.important===1&&<Flag size={12}/>}</strong><small>{item.quantity} {item.unit}{item.store?' · '+(stores.find(s=>s.id===item.store)?.name||item.store):''}{item.note?' · '+item.note:''}</small></button><strong className="item-price">{item.price===null?'—':money(Math.round(item.price*item.quantity))}</strong><button className={'icon-btn item-star '+(item.favorite?'gold':'')} aria-label="Избранный товар" disabled={busy||!['owner','editor'].includes(current.role||'')} onClick={()=>itemPatch(item,{favorite:item.favorite?0:1})}><Star size={15} fill={item.favorite?'currentColor':'none'}/></button></div>)}</section>})}{!getItems(state,current.id).some(i=>normalizedName(i.name).includes(normalizedName(search)))&&<p className="no-results">Ничего не найдено</p>}</>}{getItems(state,current.id).length>0&&<button className="inline-add" disabled={busy||current.archived===1||!['owner','editor'].includes(current.role||'')} onClick={()=>setModal({kind:'item',list:current})}><Plus size={18}/>Ещё одна покупка</button>}</div></section><aside className="summary-panel"><span className="eyebrow">ВАШ ПЛАН</span><h3>Бюджет списка</h3><div className="summary-amount">{money(listTotal(getItems(state,current.id)))}</div><p className="muted">Стоимость товаров с указанной ценой</p>{getItems(state,current.id).some(i=>i.price===null)&&<p className="small-notice">{getItems(state,current.id).filter(i=>i.price===null).length} покупок без цены — они ещё не учтены.</p>}{current.budget>0&&<><div className="summary-line"><span>Бюджет</span><strong>{money(current.budget)}</strong></div><div className={'budget-bar '+(listTotal(getItems(state,current.id))>current.budget?'over':'')}><span style={{width:Math.min(100,listTotal(getItems(state,current.id))/current.budget*100)+'%'}}/></div><div className="summary-line"><span>{listTotal(getItems(state,current.id))>current.budget?'Превышение':'Осталось'}</span><strong>{money(Math.abs(current.budget-listTotal(getItems(state,current.id))))}</strong></div></>}<div className="summary-divider"/><div className="summary-line"><span>Куплено</span><strong>{getItems(state,current.id).filter(i=>i.bought).length} / {getItems(state,current.id).length}</strong></div><button className="text-action" disabled={busy} onClick={async()=>{const result=await run({action:'duplicateList',id:current.id},'Создана копия списка');if(result)setSelected(result.id||null);}}><Copy size={15}/>Повторить покупки</button>{['owner','editor'].includes(current.role||'')&&<button className="text-action" disabled={busy} onClick={()=>{listPatch(current,{archived:current.archived?0:1});setSelected(null);}}><Archive size={15}/>{current.archived?'Восстановить список':'Убрать в архив'}</button>}<div className="summary-hint"><Leaf size={17}/><p>Отмечайте покупки по пути. Так ничего не забудется.</p></div></aside></div></> : <>
    {page==='planner'&&<WeeklyPlanner city={state.profile.city} onOpenList={async id=>{await refresh();setSelected(id);setPage('home');}}/>}
    {page==='home'&&<><div className="page-heading"><div><div className="eyebrow">{new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</div><h1>Всё нужное — под рукой<span className="heading-dot">.</span></h1><p>Хороший план освобождает время для хорошего дня.</p></div><button className="primary" onClick={()=>setModal({kind:'list'})}><Plus size={18}/>Новый список</button></div><section className="hero"><div><span className="pill light"><Leaf size={13}/>ПОКУПКИ БЕЗ ЛИШНЕЙ СУЕТЫ</span><h2>Соберите список.<br/>Освободите голову.</h2><p>От идеи на ужин до покупок на неделю —<br className="desktop-br"/> всё начинается с простого плана.</p><button onClick={()=>go('planner')}>Спланировать покупки<ArrowUpRight size={17}/></button></div><div className="hero-illustration" aria-hidden="true"><span className="hero-spark spark-one">✦</span><span className="hero-spark spark-two">✧</span><div className="grocery-bag"><div className="bag-handle"/><span className="bag-food avocado">🥑</span><span className="bag-food carrot">🥕</span><span className="bag-food baguette">🥖</span><div className="bag-front"><ShoppingBasket size={44}/><span>хороший план</span></div></div><div className="floating-check"><CheckCircle2 size={21}/><span>Всё собрано</span></div></div></section><div className="stats-grid"><div className="stat-card"><span className="stat-icon green"><ClipboardList size={21}/></span><div><strong>{activeLists.length}</strong><span>Активных списков</span></div></div><div className="stat-card"><span className="stat-icon peach"><ShoppingBasket size={21}/></span><div><strong>{remaining.length}</strong><span>Осталось купить</span></div></div><div className="stat-card"><span className="stat-icon sand"><PieChart size={21}/></span><div><strong>{money(total)}</strong><span>По указанным ценам</span></div></div></div><div className="section-title"><h2>Мои списки <span className="count">{activeLists.length}</span></h2><button className="text-action" onClick={()=>go('calendar')}><CalendarDays size={15}/>Посмотреть календарь<ChevronRight size={14}/></button></div><div className="filters-row"><div className="tabs">{['Все','Личные','Общие','Избранные','Архив'].map(f=><button key={f} className={listFilter===f?'active':''} onClick={()=>setListFilter(f)}>{f}</button>)}</div><div className="searchbox compact"><Search size={16}/><input aria-label="Найти список" placeholder="Найти список" value={search} onChange={e=>setSearch(e.target.value)}/></div></div><div className="lists-grid">{state.lists.filter(l=>(listFilter==='Архив'?l.archived:!l.archived)&&(listFilter!=='Личные'||!l.groupId)&&(listFilter!=='Общие'||l.groupId)&&(listFilter!=='Избранные'||l.favorite)&&normalizedName(l.name).includes(normalizedName(search))).map(l=><ListCard key={l.id} list={l}/>)}<button className="new-list-card" onClick={()=>setModal({kind:'list'})}><span><Plus size={26}/></span><strong>Ещё один хороший план</strong><p>Создать новый список</p></button></div><section className="recipe-home"><div className="section-title"><div><span className="eyebrow">ВДОХНОВЕНИЕ НА КАЖДЫЙ ДЕНЬ</span><h2>А что на ужин?</h2></div><button className="text-action" onClick={()=>go('recipes')}>Все рецепты<ArrowUpRight size={16}/></button></div><div className="recipe-grid small-grid">{state.recipes.slice(1,4).map(r=><RecipeCard key={r.id} recipe={r} favorite={favorites.includes(r.id)} onOpen={()=>openRecipe(r)} onFavorite={()=>recipeFavorite(r)}/>)}</div></section></>}
    {page==='calendar'&&<><div className="page-heading"><div><div className="eyebrow">ПЛАНЫ НА НЕДЕЛЮ</div><h1>У покупок тоже есть свой день.</h1><p>Выберите дату, чтобы собрать всё вовремя.</p></div><button className="primary" onClick={()=>setModal({kind:'list'})}><Plus size={18}/>Запланировать</button></div><div className="calendar-layout"><section className="calendar-panel"><header><h2>{calendarMonth.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</h2><div><button className="icon-btn" aria-label="Предыдущий месяц" onClick={()=>setCalendarMonth(new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()-1,1))}><ChevronLeft size={18}/></button><button className="text-action" onClick={()=>{setCalendarMonth(new Date());setCalendarDay(today);}}>Сегодня</button><button className="icon-btn" aria-label="Следующий месяц" onClick={()=>setCalendarMonth(new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1))}><ChevronRight size={18}/></button></div></header><div className="calendar-grid">{['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(d=><span className="day-name" key={d}>{d}</span>)}{Array.from({length:(new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1).getDay()+6)%7},(_,i)=><div className="calendar-blank" key={'blank'+i}/>)}{Array.from({length:new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,0).getDate()},(_,i)=>{const day=localDate(new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),i+1)),dayLists=activeLists.filter(l=>l.date===day);return <button key={day} className={'calendar-cell '+(day===calendarDay?'selected':'')+(day===today?' today':'')} onClick={()=>setCalendarDay(day)}><span>{i+1}</span>{dayLists.slice(0,2).map(l=><small key={l.id}>{l.icon} {l.name}</small>)}{dayLists.length>2&&<small>+{dayLists.length-2}</small>}</button>})}</div></section><aside className="day-plans"><span className="eyebrow">ВАШ ПЛАН</span><h2>{humanDate(calendarDay)}</h2>{activeLists.filter(l=>l.date===calendarDay).map(l=><ListCard key={l.id} list={l}/>)}{!activeLists.some(l=>l.date===calendarDay)&&<Empty emoji="🌿" title="Свободный день" text="Здесь появятся списки, запланированные на эту дату."/>}<button className="secondary" onClick={()=>setModal({kind:'list'})}><Plus size={16}/>Добавить план</button></aside></div></>}
    {page==='recipes'&&<><div className="page-heading"><div><div className="eyebrow">ВАША КУЛИНАРНАЯ КНИГА</div><h1>Что приготовим сегодня?</h1><p>Выберите блюдо — ингредиенты отправятся в список.</p></div><button className="primary" onClick={()=>setModal({kind:'newRecipe'})}><Plus size={18}/>Мой рецепт</button></div><div className="filters-row"><div className="tabs">{['Все','Завтрак','Обед','Ужин','Салат','Избранное','Мои'].map(f=><button key={f} className={recipeFilter===f?'active':''} onClick={()=>setRecipeFilter(f)}>{f}</button>)}</div><div className="searchbox"><Search size={16}/><input aria-label="Поиск рецептов" placeholder="Рецепт или ингредиент" value={search} onChange={e=>setSearch(e.target.value)}/></div></div><div className="recipe-grid">{state.recipes.filter(r=>(recipeFilter==='Все'||r.category===recipeFilter||(recipeFilter==='Избранное'&&favorites.includes(r.id))||(recipeFilter==='Мои'&&r.own))&&normalizedName(r.name+' '+r.ingredients.map(i=>i.name).join(' ')).includes(normalizedName(search))).map(r=><RecipeCard key={r.id} recipe={r} favorite={favorites.includes(r.id)} onOpen={()=>openRecipe(r)} onFavorite={()=>recipeFavorite(r)}/>)}</div>{!state.recipes.some(r=>(recipeFilter==='Все'||r.category===recipeFilter||(recipeFilter==='Избранное'&&favorites.includes(r.id))||(recipeFilter==='Мои'&&r.own))&&normalizedName(r.name+' '+r.ingredients.map(i=>i.name).join(' ')).includes(normalizedName(search)))&&<Empty emoji="🍽️" title="Пока без рецептов" text="Измените фильтр или добавьте своё любимое блюдо."/>}</>}
    {page==='catalog'&&<><div className="page-heading"><div><div className="eyebrow">ТОВАРЫ И ПРЕДЛОЖЕНИЯ</div><h1>Покупки начинаются с выбора.</h1><p>Цены с открытых страниц магазинов, с датой проверки.</p></div><button className="secondary" onClick={()=>void syncCatalog()}><RefreshCw size={16}/>Обновить цены</button></div><div className="stores-row"><button className={'store-chip '+(storeFilter==='all'?'active':'')} onClick={()=>setStoreFilter('all')}><Store size={18}/>Все магазины</button>{stores.map(s=><button key={s.id} className={'store-chip '+(storeFilter===s.id?'active':'')} onClick={()=>setStoreFilter(s.id)}><span style={{background:s.color}}>{s.short}</span>{s.name}</button>)}</div><div className="filters-row"><div className="searchbox catalog-search"><Search size={18}/><input aria-label="Поиск товаров" placeholder="Товар, бренд или штрихкод" value={search} onChange={e=>setSearch(e.target.value)}/></div><button className={'secondary '+(compare?'selected':'')} onClick={()=>setCompare(!compare)}><PieChart size={16}/>{compare?'Обычный каталог':'Сравнить цены'}</button><button className="secondary" onClick={()=>setModal({kind:'source'})}><Plus size={16}/>Подключить источник</button></div><div className="notice"><ShieldCheck size={18}/><span>Цены зависят от адреса, магазина и карты лояльности. Регион открытой страницы может отличаться от вашего города.</span></div>{compare&&<div className="notice"><Search size={17}/><span>Сравниваются одинаковые штрихкоды или точные названия и единицы. Сходные названия не гарантируют одинаковый товар.</span></div>}<div className="catalog-grid">{state.products.filter(p=>state.sources.some(s=>s.id===p.sourceId&&s.enabled)&&(storeFilter==='all'||p.store===storeFilter)&&normalizedName(p.name+' '+(p.barcode||'')).includes(normalizedName(search))).sort((a,b)=>compare?normalizedName(a.name).localeCompare(normalizedName(b.name))||a.price-b.price:0).slice(0,catalogLimit).map(p=>{const identical=state.products.filter(x=>x.unit===p.unit&&((p.barcode&&x.barcode===p.barcode)||(!p.barcode&&!x.barcode&&normalizedName(x.name)===normalizedName(p.name)))),best=compare&&identical.length>1&&p.price===Math.min(...identical.map(x=>x.price));return <article className="product-card" key={p.id}><div className="product-image">{p.image?<img src={p.image} alt={p.name} loading="lazy"/>:<span>🛍️</span>}{best&&<b>Лучшая цена</b>}</div><span className="product-store">{stores.find(s=>s.id===p.store)?.name}</span><h3>{p.name}</h3><div className="product-price"><strong>{money(p.price)}</strong><span>/ {p.unit}</span></div><small>{p.city} · {new Date(p.updatedAt).toLocaleDateString('ru-RU')}{Date.now()-Date.parse(p.updatedAt)>6*3600000?' · требует обновления':''}</small><div className="product-actions"><a href={p.url} target="_blank" rel="noopener noreferrer" aria-label="Открыть товар в магазине"><ExternalLink size={16}/></a><button className="primary" onClick={()=>{setTargetList(activeLists[0]?.id||'');setModal({kind:'product',product:p});}}><Plus size={16}/>В список</button></div></article>})}</div>{state.products.filter(p=>state.sources.some(s=>s.id===p.sourceId&&s.enabled)&&(storeFilter==='all'||p.store===storeFilter)&&normalizedName(p.name+' '+(p.barcode||'')).includes(normalizedName(search))).length>catalogLimit&&<button className="secondary wide" onClick={()=>setCatalogLimit(n=>n+48)}>Показать ещё 48 товаров</button>}{!state.products.some(p=>(storeFilter==='all'||p.store===storeFilter)&&state.sources.some(s=>s.id===p.sourceId&&s.enabled)&&normalizedName(p.name+' '+(p.barcode||'')).includes(normalizedName(search)))&&<div className="empty bordered"><div className="empty-emoji">🛍️</div><h3>{search?'Товары не найдены':'Каталог ждёт обновления'}</h3><p>{search?'Попробуйте другое название или выберите все магазины.':'Нажмите «Обновить цены». В каталоге появятся только предложения, полученные от магазина.'}</p><button className="primary" onClick={()=>void syncCatalog()}><RefreshCw size={16}/>Проверить источники</button></div>}<div className="section-title"><h2>Источники цен</h2><span className="muted">Автопроверка при открытии · раз в 6 часов</span></div><div className="sources-list">{state.sources.filter(s=>storeFilter==='all'||s.store===storeFilter).map(source=><div className="source-row" key={source.id}><span className={'source-status '+source.status}>{source.status==='ok'?<Check size={17}/>:<Store size={17}/>}</span><div><strong>{stores.find(s=>s.id===source.store)?.name} <small>{source.city}</small></strong><p>{source.enabled?source.message:'Источник приостановлен'}</p><small>{source.lastSuccess?'Проверено: '+new Date(source.lastSuccess).toLocaleString('ru-RU'):'Успешного обновления ещё не было'}</small></div><button className="icon-btn" disabled={busy||!source.enabled} aria-label="Обновить источник" onClick={()=>void run({action:'sync',sourceId:source.id},'Проверка завершена')}><RefreshCw size={16}/></button><button className="text-action" disabled={busy||source.id==='vkusvill-makarony'} onClick={()=>void run({action:'toggleSource',id:source.id,enabled:source.enabled?0:1})}>{source.enabled?'Пауза':'Включить'}</button></div>)}</div></>}
    {page==='groups'&&<><div className="page-heading"><div><div className="eyebrow">СЕМЬЯ, ДРУЗЬЯ И ОБЩИЕ ПЛАНЫ</div><h1>Хорошие планы объединяют.</h1><p>Один список. Все знают, что ещё нужно купить.</p></div><button className="primary" onClick={()=>setModal({kind:'group'})}><Plus size={18}/>Создать группу</button></div><div className="notice"><Users size={18}/><span>Приложение сейчас личное. Для участия другого человека ему также нужен доступ к этому сайту; одной ссылки группы недостаточно.</span></div><div className="groups-grid">{state.groups.map(group=><article className="group-card" key={group.id}><div className="group-card-top"><span className="stat-icon green"><Users size={23}/></span><span className="pill">{group.role==='owner'?'Владелец':group.role==='editor'?'Редактор':group.role==='shopper'?'Покупатель':'Наблюдатель'}</span></div><h2>{group.name}</h2><p>{activeLists.filter(l=>l.groupId===group.id).length} общих списков · {group.members.length} участников</p><div className="members">{group.members.map(m=><div key={m.id}><span className="avatar small">{m.name.slice(0,1)}</span><span><strong>{m.name}</strong><small>{m.role==='owner'?'Владелец':m.role==='editor'?'Может редактировать':m.role==='shopper'?'Отмечает покупки':'Только просмотр'}</small></span>{group.role==='owner'&&m.role!=='owner'&&<button className="icon-btn" aria-label="Удалить участника" disabled={busy} onClick={()=>void run({action:'removeMember',groupId:group.id,userId:m.userId})}><X size={15}/></button>}</div>)}</div>{group.role==='owner'&&<button className="secondary wide" onClick={()=>setModal({kind:'invite',groupId:group.id})}><LinkIcon size={16}/>Пригласить по ссылке</button>}{activeLists.filter(l=>l.groupId===group.id).map(l=><button className="group-list-link" key={l.id} onClick={()=>{setSelected(l.id);setSearch('');}}>{l.icon} {l.name}<ChevronRight size={16}/></button>)}</article>)}</div>{state.groups.length===0&&<Empty emoji="🤝" title="Покупайте вместе" text="Создайте группу, затем назначьте ей список покупок."/>}</>}
    {page==='spending'&&<><div className="page-heading"><div><div className="eyebrow">ВАШ БЮДЖЕТ</div><h1>Покупки в цифрах.</h1><p>Расчёт по отмеченным покупкам и введённым ценам.</p></div></div><div className="stats-grid"><div className="stat-card"><span className="stat-icon green"><CheckCircle2 size={22}/></span><div><strong>{money(listTotal(state.items.filter(i=>i.bought)))}</strong><span>Отмечено купленным</span></div></div><div className="stat-card"><span className="stat-icon peach"><ShoppingBasket size={22}/></span><div><strong>{money(listTotal(remaining))}</strong><span>Ещё запланировано</span></div></div><div className="stat-card"><span className="stat-icon sand"><PieChart size={22}/></span><div><strong>{state.items.filter(i=>i.bought&&i.price===null).length}</strong><span>Купленных без цены</span></div></div></div><div className="notice"><PieChart size={17}/><span>Суммы рассчитываются по текущей цене в списке. Это личный ориентир бюджета; чеки и банковские операции не подключены.</span></div><section className="spending-panel"><h2>По категориям</h2>{[...new Set(state.items.filter(i=>i.bought).map(i=>i.category))].map(category=>{const value=listTotal(state.items.filter(i=>i.bought&&i.category===category)),sum=listTotal(state.items.filter(i=>i.bought));return <div className="expense-row" key={category}><div><span>{categoryEmoji[category]||'📦'}</span><strong>{category}</strong></div><div className="expense-bar"><span style={{width:sum?Math.max(1,value/sum*100)+'%':'0%'}}/></div><strong>{money(value)}</strong></div>})}{!state.items.some(i=>i.bought)&&<Empty emoji="📊" title="Первые покупки — первые цифры" text="Укажите цены в списке и отмечайте покупки. Здесь появятся суммы по категориям."/>}</section></>}
    {page==='settings'&&<><div className="page-heading"><div><div className="eyebrow">НАСТРОЙКИ</div><h1>Ваше пространство.</h1><p>Всё так, как вам удобно.</p></div></div><div className="settings-grid"><section className="settings-card"><h2>Профиль</h2><form onSubmit={async event=>{event.preventDefault();const form=new FormData(event.currentTarget);await run({action:'profile',name:field(form,'name'),city:field(form,'city')},'Профиль сохранён');}}><label>Как к вам обращаться<input name="name" defaultValue={state.profile.name} required maxLength={100}/></label><label>Ваш город<input name="city" defaultValue={state.profile.city} required maxLength={100} list="cities"/><datalist id="cities"><option>Москва</option><option>Санкт-Петербург</option><option>Нижний Новгород</option><option>Казань</option></datalist></label><p className="muted small">Город помогает планировать покупки. Регион цен проверяйте на странице магазина.</p><button className="primary" disabled={busy}>Сохранить</button></form><div className="account-label"><ShieldCheck size={17}/><span>Вход через ChatGPT<br/><small>{state.profile.email}</small></span></div><a className="text-action" href="/signout-with-chatgpt?return_to=/" target="_top">Выйти из аккаунта</a></section><section className="settings-card"><h2>Оформление</h2><div className="theme-options">{[{id:'light',label:'Светлая',Icon:Sun},{id:'dark',label:'Тёмная',Icon:Moon},{id:'system',label:'Как на устройстве',Icon:Settings}].map(t=><button key={t.id} disabled={busy} className={state.profile.theme===t.id?'selected':''} onClick={()=>void run({action:'profile',theme:t.id})}><t.Icon size={22}/><span>{t.label}</span></button>)}</div><h2 className="spaced">Всегда под рукой</h2><p>Добавьте «Собрано» на главный экран телефона.</p><button className="secondary wide" onClick={()=>{if(installPrompt)void installPrompt.prompt();else setModal({kind:'install'});}}><Download size={17}/>Установить приложение</button></section><section className="settings-card"><h2>Ваши данные</h2><p>Списки, рецепты и настройки сохраняются в вашем аккаунте. Можно скачать копию.</p><button className="secondary wide" onClick={exportFile}><Download size={17}/>Экспортировать данные</button><button className="text-action" onClick={()=>refresh().then(()=>notify('Данные обновлены')).catch(()=>notify('Не удалось обновить'))}><RefreshCw size={16}/>Обновить с другого устройства</button></section><section className="settings-card"><h2>Источники магазинов</h2><p>{state.sources.filter(s=>s.enabled).length} активных источников. Проверяются при открытии каталога, не чаще раза в 6 часов.</p><button className="secondary wide" onClick={()=>go('catalog')}><Store size={17}/>Открыть подключения</button><p className="muted small">Версия 0.3 · личный доступ<br/>Все реализованные возможности доступны бесплатно.</p></section></div></>}
    </>}
    <footer className="app-footer"><span>собрано<span className="brand-dot">.</span></span><p>Хороший план. Спокойный день.</p><span>Для себя и близких</span></footer></main></div>
    <nav className="mobile-nav" aria-label="Мобильная навигация">{navigation.slice(0,4).map(n=><button key={n.id} className={page===n.id?'active':''} onClick={()=>go(n.id as Page)}><n.icon size={21}/><span>{n.id==='home'?'Списки':n.id==='planner'?'Меню':n.name}</span></button>)}<button onClick={()=>setMobileMenu(true)}><Menu size={21}/><span>Ещё</span></button></nav>
    {toast&&<div className="toast" role="status"><CheckCircle2 size={18}/>{toast}<button aria-label="Закрыть уведомление" onClick={()=>setToast('')}><X size={15}/></button></div>}
    {modal&&<Modal title={modal.kind==='list'?(modal.list?'Настроить список':'Новый хороший план'):modal.kind==='item'?(modal.item?'Редактировать покупку':'Добавить покупку'):modal.kind==='recipe'?modal.recipe!.name:modal.kind==='newRecipe'?'Ваш любимый рецепт':modal.kind==='group'?'Новая группа':modal.kind==='invite'?'Пригласить близких':modal.kind==='join'?'Вас пригласили в группу':modal.kind==='source'?'Подключить магазин':modal.kind==='product'?'Добавить в список':'Всегда под рукой'} subtitle={modal.kind==='item'?'Название, количество и важные детали':modal.kind==='list'?'Покупки начинаются с простого списка':undefined} onClose={close}>
      {modal.kind==='list'&&<form className="modal-form" onSubmit={submitList}><label>Название<input name="name" defaultValue={modal.list?.name} placeholder="Например, покупки на неделю" required maxLength={200} autoFocus/></label><div className="form-row"><label>Значок<select name="icon" defaultValue={modal.list?.icon||'🛒'}>{['🛒','🏡','🥑','🎉','🐶','✈️','🎁','🥐','👶','🏕️','☕','✨'].map(i=><option key={i}>{i}</option>)}</select></label><label>Бюджет, ₽<input name="budget" type="number" min="0" step="0.01" defaultValue={modal.list?.budget?modal.list.budget/100:''} placeholder="Без ограничения"/></label></div><label>День покупок<input name="date" type="date" defaultValue={modal.list?.date||(page==='calendar'?calendarDay:'')}/></label><label>Кто покупает<select name="group" disabled={!!modal.list&&modal.list.role!=='owner'} defaultValue={modal.list?.groupId||''}><option value="">Только я</option>{state.groups.filter(g=>g.role==='owner').map(g=><option key={g.id} value={g.id}>{g.name}</option>)}</select></label><button className="primary wide" disabled={busy}>{busy?'Сохраняем…':modal.list?'Сохранить изменения':'Создать список'}</button></form>}
      {modal.kind==='item'&&<form className="modal-form" onSubmit={submitItem}><label>Название<div className="input-with-action"><input id="item-name" name="name" defaultValue={modal.item?.name} placeholder="Например, молоко" required maxLength={200}/><button type="button" aria-label="Надиктовать покупку" onClick={()=>void dictate()}><Mic size={18}/></button></div></label><div className="form-row"><label>Количество<input name="quantity" type="number" min="0.001" max="100000" step="0.001" defaultValue={modal.item?.quantity??1} required/></label><label>Единица<select name="unit" defaultValue={modal.item?.unit||'шт'}>{['шт','кг','г','л','мл','уп'].map(u=><option key={u}>{u}</option>)}</select></label><label>Цена за единицу, ₽<input name="price" type="number" min="0" step="0.01" defaultValue={modal.item?.price===null||modal.item?.price===undefined?'':modal.item.price/100} placeholder="Не указана"/></label></div><label>Категория<select name="category" defaultValue={modal.item?.category||'Продукты'}>{categories.map(c=><option key={c}>{c}</option>)}</select></label><label>Заметка<input name="note" defaultValue={modal.item?.note} maxLength={1000} placeholder="Бренд, размер или пожелание"/></label><label className="checkbox-label"><input name="important" type="checkbox" defaultChecked={!!modal.item?.important}/><Flag size={15}/>Важная покупка</label>{!modal.item&&<details className="barcode-details"><summary><ScanLine size={17}/>Штрихкод и камера</summary><label>Штрихкод<input id="item-barcode" name="barcode" inputMode="numeric" pattern="[0-9]{8,14}" placeholder="8–14 цифр"/></label><video ref={video} playsInline muted className="scan-video"/><p className="small">Поиск названия работает для штрихкодов, уже известных каталогу.</p>{scanError&&<p className="inline-error">{scanError}</p>}<button type="button" className="secondary" onClick={()=>void startScan()}><ScanLine size={16}/>Сканировать</button></details>}<button className="primary wide" disabled={busy}>{busy?'Сохраняем…':modal.item?'Сохранить':'Добавить в список'}</button>{modal.item&&<button type="button" className="text-action danger" disabled={busy} onClick={async()=>{const result=await run({action:'updateItem',id:modal.item!.id,revision:modal.item!.revision,deleted:1},'Товар убран из списка');if(result)close();}}><Trash2 size={15}/>Убрать покупку</button>}{!modal.item&&state.items.some(i=>i.favorite)&&<div className="favorite-picker"><span className="eyebrow">ИЗБРАННЫЕ ТОВАРЫ</span>{[...new Map(state.items.filter(i=>i.favorite).map(i=>[i.name,i])).values()].slice(0,8).map(i=><button key={i.id} type="button" className="chip" onClick={async()=>{const result=await run({action:'addItems',listId:modal.list?.id||selected,items:[{name:i.name,quantity:i.quantity,unit:i.unit,price:i.price,category:i.category,note:i.note}]},'Избранный товар добавлен');if(result)close();}}>{categoryEmoji[i.category]||'🛒'} {i.name}<Plus size={13}/></button>)}</div>}</form>}
      {modal.kind==='recipe'&&<div className="recipe-detail"><div className="recipe-detail-art" style={{background:modal.recipe!.color}}>{modal.recipe!.emoji}<span>{modal.recipe!.time} минут · {modal.recipe!.category}</span></div><div className="recipe-detail-content"><div className="section-title"><h3>Ингредиенты</h3><div className="portion-control"><button aria-label="Меньше порций" onClick={()=>setPortions(Math.max(1,portions-1))}><Minus size={15}/></button><span>{portions} порции</span><button aria-label="Больше порций" onClick={()=>setPortions(Math.min(100,portions+1))}><Plus size={15}/></button></div></div>{modal.recipe!.ingredients.map((i,index)=><div className="ingredient" key={index}><span>{i.name}</span><strong>{Math.round(i.quantity*portions/modal.recipe!.portions*1000)/1000} {i.unit}</strong></div>)}<label className="recipe-target">Добавить ингредиенты в<select value={targetList} onChange={e=>setTargetList(e.target.value)}><option value="">Новый список для рецепта</option>{activeLists.filter(l=>['owner','editor'].includes(l.role||'')).map(l=><option key={l.id} value={l.id}>{l.icon} {l.name}</option>)}</select></label><button className="primary wide" disabled={busy} onClick={async()=>{let listId=targetList;if(!listId){const created=await run({action:'createList',name:modal.recipe!.name,icon:modal.recipe!.emoji});if(!created)return;listId=created.id||'';}const result=await run({action:'addItems',listId,items:modal.recipe!.ingredients.map(i=>({name:i.name,quantity:Math.round(i.quantity*portions/modal.recipe!.portions*1000)/1000,unit:i.unit,category:i.category||'Продукты',price:null,note:modal.recipe!.name}))},'Ингредиенты добавлены в список');if(result){close();setSelected(listId);setPage('home');}}}><ShoppingBasket size={17}/>В список покупок</button><div className="cooking-steps"><div className="section-title"><h3>Готовим по шагам</h3><span className="muted">{recipeStep+1} / {modal.recipe!.steps.length}</span></div><div className="cooking-step"><span>{String(recipeStep+1).padStart(2,'0')}</span><p>{modal.recipe!.steps[recipeStep]}</p></div><div className="step-buttons"><button className="secondary" disabled={recipeStep===0} onClick={()=>setRecipeStep(recipeStep-1)}><ChevronLeft size={16}/>Назад</button><button className="primary" disabled={recipeStep===modal.recipe!.steps.length-1} onClick={()=>setRecipeStep(recipeStep+1)}>Следующий<ChevronRight size={16}/></button></div></div></div></div>}
      {modal.kind==='newRecipe'&&<RecipeEditor busy={busy} onSubmit={async recipe=>{const result=await run({action:'createRecipe',...recipe},'Рецепт сохранён');if(result)close();}}/>}
      {modal.kind==='group'&&<form className="modal-form" onSubmit={async e=>{e.preventDefault();const result=await run({action:'createGroup',name:field(new FormData(e.currentTarget),'name')},'Группа создана');if(result)close();}}><label>Название группы<input name="name" required placeholder="Например, наша семья" maxLength={200}/></label><p className="muted">После создания назначьте группу новому или существующему списку.</p><button className="primary wide" disabled={busy}>Создать группу</button></form>}
      {modal.kind==='invite'&&<form className="modal-form" onSubmit={async e=>{e.preventDefault();const result=await run({action:'invite',groupId:modal.groupId,role:field(new FormData(e.currentTarget),'role')});if(result)setInviteLink(location.origin+'/#join='+result.token);}}><label>Права участника<select name="role"><option value="editor">Добавлять, менять и отмечать покупки</option><option value="shopper">Только отмечать покупки</option><option value="viewer">Только смотреть</option></select></label><p className="muted">Ссылка действует 7 дней. Другому человеку нужен доступ к личному сайту.</p><button className="primary wide" disabled={busy}><LinkIcon size={16}/>Создать приглашение</button>{inviteLink&&<label>Ссылка приглашения<input readOnly value={inviteLink}/><button type="button" className="secondary" onClick={()=>void copyText(inviteLink)}><Copy size={16}/>Скопировать</button></label>}<button type="button" className="text-action danger" disabled={busy} onClick={()=>void run({action:'revokeInvites',groupId:modal.groupId},'Все прежние приглашения отозваны')}>Отозвать прежние приглашения</button></form>}
      {modal.kind==='join'&&<div className="modal-form"><p>Примите приглашение, чтобы видеть списки группы. Права назначает её владелец.</p><button className="primary wide" disabled={busy} onClick={async()=>{const result=await run({action:'join',token:modal.token},'Вы присоединились к группе');if(result){history.replaceState(null,'',location.pathname);close();go('groups');}}}>Принять приглашение</button></div>}
      {modal.kind==='source'&&<SourceEditor city={state.profile.city} busy={busy} onSubmit={async data=>{const result=await run({action:'addSource',...data},'Источник добавлен');if(result){close();void run({action:'sync',sourceId:result.id});}}}/>}
      {modal.kind==='product'&&<form className="modal-form" onSubmit={async e=>{e.preventDefault();let listId=targetList;if(!listId){const created=await run({action:'createList',name:'Покупки',icon:'🛒'});if(!created)return;listId=created.id||'';}const p=modal.product!,form=new FormData(e.currentTarget),result=await run({action:'addItems',listId,items:[{name:p.name,quantity:num(form,'quantity',1),unit:p.unit,price:p.price,category:p.category,barcode:p.barcode,store:p.store,sourceUrl:p.url,note:'Цена со страницы магазина · '+new Date(p.updatedAt).toLocaleDateString('ru-RU')}]},'Товар добавлен');if(result)close();}}><p><strong>{modal.product!.name}</strong><br/>{money(modal.product!.price)} / {modal.product!.unit}</p><label>Список<select value={targetList} onChange={e=>setTargetList(e.target.value)}><option value="">Создать новый список</option>{activeLists.filter(l=>['owner','editor'].includes(l.role||'')).map(l=><option key={l.id} value={l.id}>{l.name}</option>)}</select></label><label>Количество<input name="quantity" type="number" defaultValue="1" required min="0.001" step="0.001"/></label><button className="primary wide" disabled={busy}>Добавить покупку</button></form>}
      {modal.kind==='install'&&<div className="modal-form"><p><strong>iPhone / iPad</strong><br/>Откройте сайт в Safari → «Поделиться» → «На экран Домой».</p><p><strong>Android</strong><br/>Откройте меню Chrome → «Добавить на главный экран» или «Установить приложение».</p><p><strong>Компьютер</strong><br/>Используйте кнопку установки в адресной строке браузера, если она доступна.</p><p className="muted">Для сохранения и обновления покупок нужен интернет. Публикация в магазинах приложений ещё не выполнена.</p></div>}
    </Modal>}
  </div>;
}

function SourceEditor({city,busy,onSubmit}:{city:string;busy:boolean;onSubmit:(data:Record<string,string>)=>Promise<void>}){const [store,setStore]=useState('vkusvill');return <form className="modal-form" onSubmit={e=>{e.preventDefault();const form=new FormData(e.currentTarget);void onSubmit({store,city:field(form,'city'),url:field(form,'url')});}}><label>Магазин<select value={store} onChange={e=>setStore(e.target.value)}>{stores.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>Регион страницы магазина<input name="city" placeholder={city} defaultValue="Регион не подтверждён" required maxLength={200}/></label><label>Открытая страница категории или товара<input key={store} name="url" type="url" defaultValue={store==='vkusvill'?'https://vkusvill.ru/goods/krupy-makarony-muka/makarony/':stores.find(s=>s.id===store)?.url||''} required placeholder="https://…"/></label><p className="muted">Для «ВкусВилла» подключён сбор страниц категорий. Другие магазины поддерживаются, если публикуют цены в стандартной разметке; некоторым потребуется отдельное подключение.</p><button className="primary wide" disabled={busy}>Подключить и проверить</button></form>;}
function RecipeEditor({busy,onSubmit}:{busy:boolean;onSubmit:(data:Record<string,unknown>)=>Promise<void>}){const [ingredients,setIngredients]=useState(3);return <form className="modal-form" onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void onSubmit({name:field(f,'name'),subtitle:field(f,'subtitle')||'Мой любимый рецепт',time:num(f,'time',20),portions:num(f,'portions',2),category:field(f,'category'),ingredients:Array.from({length:ingredients},(_,i)=>({name:field(f,'ingredient'+i),quantity:num(f,'quantity'+i,1),unit:field(f,'unit'+i)})).filter(i=>i.name),steps:field(f,'steps').split('\n').map(s=>s.trim()).filter(Boolean)});}}><label>Название блюда<input name="name" required maxLength={200} placeholder="Ваш фирменный рецепт"/></label><label>Короткое описание<input name="subtitle" maxLength={200} placeholder="За что вы любите это блюдо"/></label><div className="form-row"><label>Время, мин<input name="time" type="number" min="1" max="1440" required defaultValue="20"/></label><label>Порции<input name="portions" type="number" min="1" max="100" required defaultValue="2"/></label><label>Категория<select name="category">{['Завтрак','Обед','Ужин','Салат','Десерт'].map(c=><option key={c}>{c}</option>)}</select></label></div><h3>Ингредиенты</h3>{Array.from({length:ingredients},(_,i)=><div className="ingredient-inputs" key={i}><input aria-label={'Ингредиент '+(i+1)} name={'ingredient'+i} placeholder="Название" required={i===0}/><input aria-label={'Количество ингредиента '+(i+1)} name={'quantity'+i} type="number" min="0.001" step="0.001" defaultValue="1"/><select aria-label={'Единица ингредиента '+(i+1)} name={'unit'+i}>{['шт','г','кг','мл','л','уп'].map(u=><option key={u}>{u}</option>)}</select></div>)}<button type="button" className="text-action" disabled={ingredients>=60} onClick={()=>setIngredients(ingredients+1)}><Plus size={16}/>Ещё ингредиент</button><label>Приготовление<textarea name="steps" required rows={5} placeholder="Каждый шаг — с новой строки"/></label><button className="primary wide" disabled={busy}>Сохранить рецепт</button></form>;}
